import click
from click.testing import CliRunner


class Foo:
    pass


class Bar:
    pass


def test_flag_value_class_default_not_instantiated():
    seen = []

    @click.command()
    @click.option("--foo", "ty", flag_value=Foo, type=click.UNPROCESSED, default=True)
    @click.option("--bar", "ty", flag_value=Bar, type=click.UNPROCESSED)
    def main(ty):
        seen.append(ty)

    result = CliRunner().invoke(main, [])
    assert result.exit_code == 0, result.output
    assert seen == [Foo]

import click
from click.testing import CliRunner


class FakeVersion:
    """Mimics semver.Version: equality with a str parses the str and raises on ""."""

    def __init__(self, s):
        self.s = s

    def __str__(self):
        return self.s

    def __eq__(self, other):
        if isinstance(other, str):
            raise ValueError(f"{other!r} is not valid SemVer string")
        return NotImplemented

    __hash__ = object.__hash__


def test_help_with_custom_object_default():
    @click.command()
    @click.option("--version", default=FakeVersion("1.0.0"), show_default=True)
    def cli(version):
        pass

    result = CliRunner().invoke(cli, ["--help"])
    assert result.exception is None, result.output
    assert result.exit_code == 0
    assert "1.0.0" in result.output

import click
from click.testing import CliRunner


def test_missing_argument_hint_skips_shadowed_help_option():
    @click.group(context_settings={"help_option_names": ["-h", "--help"]})
    def cli():
        pass

    @click.command()
    @click.argument("required_arg")
    @click.option("--host", "-h", "host", default="localhost")
    def foo(required_arg, host):
        click.echo(f"Foo command required_arg={required_arg} host={host}")

    cli.add_command(foo)

    result = CliRunner().invoke(cli, ["foo"], prog_name="cli")

    assert result.exit_code == 2
    assert "Try 'cli foo --help' for help." in result.output
    assert "Try 'cli foo -h' for help." not in result.output

import click
from click.testing import CliRunner


@click.command()
def cmd_confirm():
    click.confirm(click.style("Hello World!", fg="green"), abort=True)


def test_confirm_strips_ansi_with_color_false():
    runner = CliRunner()
    result = runner.invoke(cmd_confirm, input="Y", color=False)
    assert result.output == "Hello World! [y/N]: Y\n"

import click
import click._termui_impl


def test_progressbar_show_pos_full_completion_with_update_min_steps(
    runner, monkeypatch
):
    monkeypatch.setattr(click._termui_impl, "isatty", lambda _: True)

    @click.command()
    def cli():
        with click.progressbar(
            range(20), show_pos=True, update_min_steps=7
        ) as bar:
            for _ in bar:
                pass

    result = runner.invoke(cli, [], catch_exceptions=False)
    # The final rendered position must reach 20/20, not stall at 14/20.
    assert "20/20" in result.output
